#!/usr/bin/env bash
# Reminds any agent editing a .rs file to follow the scadoshi-rust skill.
grep -Eq '"file_path" *: *"[^"]*\.rs"' && printf '%s\n' '{"hookSpecificOutput":{"hookEventName":"PreToolUse","additionalContext":"SCADOSHI-RUST: this is a Rust file. Follow the scadoshi-rust skill (load anthropic-skills:scadoshi-rust if not loaded this session). No unwrap/expect/panic/unreachable/todo or indexing outside tests (use let-else, get, ok_or, ?). Every lint suppression is #[expect(lint, reason = \"...\")], never #[allow]. Every pub fn returning Result has a # Errors doc; every pub item and module has a doc. No get_ names (bare field name, fetch_ for I/O). Free functions module-qualified (fs::read, mem::take). No glob imports. No silent as casts. Comments present tense, no history, no em dashes. A cleanup never changes behavior. Before handing back: cargo +nightly fmt, clippy --all-targets -D warnings, tests, cargo doc."}}' || true
